insert into public.teams (id, league_id, name, short_name, color, city, active)
select i.id, l.id, i.name, i.short_name, i.color, i.city, true
from input i
join public.leagues l on l.name = i.league_name and l.country_code = i.country_code
on conflict (id) do update set
  league_id = excluded.league_id, name = excluded.name, short_name = excluded.short_name,
  color = excluded.color, city = excluded.city, active = true, updated_at = now();

-- Retire clubs that are no longer in the dataset (prevents duplicates from earlier imports).
